2218 typedef enum D3D12_FILTER
2219 {
2220     // Bits used in defining enumeration of valid filters:
2221     // bits [1:0] - mip: 0 == point, 1 == linear, 2,3 unused
2222     // bits [3:2] - mag: 0 == point, 1 == linear, 2,3 unused
2223     // bits [5:4] - min: 0 == point, 1 == linear, 2,3 unused
2224     // bit  [6]   - aniso
2225     // bits [8:7] - reduction type:
2226     //                0 == standard filtering
2227     //                1 == comparison
2228     //                2 == min
2229     //                3 == max
2230     // bit  [31]  - mono 1-bit (narrow-purpose filter) [no longer supported in D3D12]
2231 
2232     D3D12_FILTER_MIN_MAG_MIP_POINT                              = 0x00000000,
2233     D3D12_FILTER_MIN_MAG_POINT_MIP_LINEAR                       = 0x00000001,
2234     D3D12_FILTER_MIN_POINT_MAG_LINEAR_MIP_POINT                 = 0x00000004,
2235     D3D12_FILTER_MIN_POINT_MAG_MIP_LINEAR                       = 0x00000005,
2236     D3D12_FILTER_MIN_LINEAR_MAG_MIP_POINT                       = 0x00000010,
2237     D3D12_FILTER_MIN_LINEAR_MAG_POINT_MIP_LINEAR                = 0x00000011,
2238     D3D12_FILTER_MIN_MAG_LINEAR_MIP_POINT                       = 0x00000014,
2239     D3D12_FILTER_MIN_MAG_MIP_LINEAR                             = 0x00000015,
2240     D3D12_FILTER_MIN_MAG_ANISOTROPIC_MIP_POINT                  = 0x00000054,
2241     D3D12_FILTER_ANISOTROPIC                                    = 0x00000055,
2242     D3D12_FILTER_COMPARISON_MIN_MAG_MIP_POINT                   = 0x00000080,
2243     D3D12_FILTER_COMPARISON_MIN_MAG_POINT_MIP_LINEAR            = 0x00000081,
2244     D3D12_FILTER_COMPARISON_MIN_POINT_MAG_LINEAR_MIP_POINT      = 0x00000084,
2245     D3D12_FILTER_COMPARISON_MIN_POINT_MAG_MIP_LINEAR            = 0x00000085,
2246     D3D12_FILTER_COMPARISON_MIN_LINEAR_MAG_MIP_POINT            = 0x00000090,
2247     D3D12_FILTER_COMPARISON_MIN_LINEAR_MAG_POINT_MIP_LINEAR     = 0x00000091,
2248     D3D12_FILTER_COMPARISON_MIN_MAG_LINEAR_MIP_POINT            = 0x00000094,
2249     D3D12_FILTER_COMPARISON_MIN_MAG_MIP_LINEAR                  = 0x00000095,
2250     D3D12_FILTER_COMPARISON_MIN_MAG_ANISOTROPIC_MIP_POINT       = 0x000000d4,
2251     D3D12_FILTER_COMPARISON_ANISOTROPIC                         = 0x000000d5,
2252     D3D12_FILTER_MINIMUM_MIN_MAG_MIP_POINT                      = 0x00000100,
2253     D3D12_FILTER_MINIMUM_MIN_MAG_POINT_MIP_LINEAR               = 0x00000101,
2254     D3D12_FILTER_MINIMUM_MIN_POINT_MAG_LINEAR_MIP_POINT         = 0x00000104,
2255     D3D12_FILTER_MINIMUM_MIN_POINT_MAG_MIP_LINEAR               = 0x00000105,
2256     D3D12_FILTER_MINIMUM_MIN_LINEAR_MAG_MIP_POINT               = 0x00000110,
2257     D3D12_FILTER_MINIMUM_MIN_LINEAR_MAG_POINT_MIP_LINEAR        = 0x00000111,
2258     D3D12_FILTER_MINIMUM_MIN_MAG_LINEAR_MIP_POINT               = 0x00000114,
2259     D3D12_FILTER_MINIMUM_MIN_MAG_MIP_LINEAR                     = 0x00000115,
2260     D3D12_FILTER_MINIMUM_MIN_MAG_ANISOTROPIC_MIP_POINT          = 0x00000154,
2261     D3D12_FILTER_MINIMUM_ANISOTROPIC                            = 0x00000155,
2262     D3D12_FILTER_MAXIMUM_MIN_MAG_MIP_POINT                      = 0x00000180,
2263     D3D12_FILTER_MAXIMUM_MIN_MAG_POINT_MIP_LINEAR               = 0x00000181,
2264     D3D12_FILTER_MAXIMUM_MIN_POINT_MAG_LINEAR_MIP_POINT         = 0x00000184,
2265     D3D12_FILTER_MAXIMUM_MIN_POINT_MAG_MIP_LINEAR               = 0x00000185,
2266     D3D12_FILTER_MAXIMUM_MIN_LINEAR_MAG_MIP_POINT               = 0x00000190,
2267     D3D12_FILTER_MAXIMUM_MIN_LINEAR_MAG_POINT_MIP_LINEAR        = 0x00000191,
2268     D3D12_FILTER_MAXIMUM_MIN_MAG_LINEAR_MIP_POINT               = 0x00000194,
2269     D3D12_FILTER_MAXIMUM_MIN_MAG_MIP_LINEAR                     = 0x00000195,
2270     D3D12_FILTER_MAXIMUM_MIN_MAG_ANISOTROPIC_MIP_POINT          = 0x000001d4,
2271     D3D12_FILTER_MAXIMUM_ANISOTROPIC                            = 0x000001d5
2272 } D3D12_FILTER;
