2280 typedef enum D3D12_FILTER_REDUCTION_TYPE
2281 {
2282     D3D12_FILTER_REDUCTION_TYPE_STANDARD = 0,
2283     D3D12_FILTER_REDUCTION_TYPE_COMPARISON = 1,
2284     D3D12_FILTER_REDUCTION_TYPE_MINIMUM = 2,
2285     D3D12_FILTER_REDUCTION_TYPE_MAXIMUM = 3,
2286 } D3D12_FILTER_REDUCTION_TYPE;
2287 
2288 const UINT D3D12_FILTER_REDUCTION_TYPE_MASK = 0x00000003;
2289 const UINT D3D12_FILTER_REDUCTION_TYPE_SHIFT = 7;
2290 
2291 const UINT D3D12_FILTER_TYPE_MASK = 0x00000003;
2292 const UINT D3D12_MIN_FILTER_SHIFT = 4;
2293 const UINT D3D12_MAG_FILTER_SHIFT = 2;
2294 const UINT D3D12_MIP_FILTER_SHIFT = 0;
2295 
2296 const UINT D3D12_ANISOTROPIC_FILTERING_BIT = 0x00000040;
2297 
2298 // encode enum entry for most filters except anisotropic filtering
2299 cpp_quote( "#define D3D12_ENCODE_BASIC_FILTER( min, mag, mip, reduction )                                                     \\" )
2300 cpp_quote( "                                   ( ( D3D12_FILTER ) (                                                           \\" )
2301 cpp_quote( "                                   ( ( ( min ) & D3D12_FILTER_TYPE_MASK ) << D3D12_MIN_FILTER_SHIFT ) |           \\" )
2302 cpp_quote( "                                   ( ( ( mag ) & D3D12_FILTER_TYPE_MASK ) << D3D12_MAG_FILTER_SHIFT ) |           \\" )
2303 cpp_quote( "                                   ( ( ( mip ) & D3D12_FILTER_TYPE_MASK ) << D3D12_MIP_FILTER_SHIFT ) |           \\" )
2304 cpp_quote( "                                   ( ( ( reduction ) & D3D12_FILTER_REDUCTION_TYPE_MASK ) << D3D12_FILTER_REDUCTION_TYPE_SHIFT ) ) ) " )
2305 
2306 // encode enum entry for anisotropic filtering (with or without comparison filtering)
2307 cpp_quote( "#define D3D12_ENCODE_ANISOTROPIC_FILTER( reduction )                                                  \\" )
2308 cpp_quote( "                                         ( ( D3D12_FILTER ) (                                         \\" )
2309 cpp_quote( "                                         D3D12_ANISOTROPIC_FILTERING_BIT |                            \\" )
2310 cpp_quote( "                                         D3D12_ENCODE_BASIC_FILTER( D3D12_FILTER_TYPE_LINEAR,         \\" )
2311 cpp_quote( "                                                                    D3D12_FILTER_TYPE_LINEAR,         \\" )
2312 cpp_quote( "                                                                    D3D12_FILTER_TYPE_LINEAR,         \\" )
2313 cpp_quote( "                                                                    reduction ) ) )                     " )
2314 cpp_quote( "#define D3D12_ENCODE_MIN_MAG_ANISOTROPIC_MIP_POINT_FILTER( reduction )                                \\" )
2315 cpp_quote( "                                         ( ( D3D12_FILTER ) (                                         \\" )
2316 cpp_quote( "                                         D3D12_ANISOTROPIC_FILTERING_BIT |                            \\" )
2317 cpp_quote( "                                         D3D12_ENCODE_BASIC_FILTER( D3D12_FILTER_TYPE_LINEAR,         \\" )
2318 cpp_quote( "                                                                    D3D12_FILTER_TYPE_LINEAR,         \\" )
2319 cpp_quote( "                                                                    D3D12_FILTER_TYPE_POINT,          \\" )
2320 cpp_quote( "                                                                    reduction ) ) )                     " )
2321 
2322 cpp_quote( "#define D3D12_DECODE_MIN_FILTER( D3D12Filter )                                                              \\" )
2323 cpp_quote( "                                 ( ( D3D12_FILTER_TYPE )                                                    \\" )
2324 cpp_quote( "                                 ( ( ( D3D12Filter ) >> D3D12_MIN_FILTER_SHIFT ) & D3D12_FILTER_TYPE_MASK ) ) " )
2325 
2326 cpp_quote( "#define D3D12_DECODE_MAG_FILTER( D3D12Filter )                                                              \\" )
2327 cpp_quote( "                                 ( ( D3D12_FILTER_TYPE )                                                    \\" )
2328 cpp_quote( "                                 ( ( ( D3D12Filter ) >> D3D12_MAG_FILTER_SHIFT ) & D3D12_FILTER_TYPE_MASK ) ) " )
2329 
2330 cpp_quote( "#define D3D12_DECODE_MIP_FILTER( D3D12Filter )                                                              \\" )
2331 cpp_quote( "                                 ( ( D3D12_FILTER_TYPE )                                                    \\" )
2332 cpp_quote( "                                 ( ( ( D3D12Filter ) >> D3D12_MIP_FILTER_SHIFT ) & D3D12_FILTER_TYPE_MASK ) ) " )
2333 
2334 cpp_quote( "#define D3D12_DECODE_FILTER_REDUCTION( D3D12Filter )                                                        \\" )
2335 cpp_quote( "                                 ( ( D3D12_FILTER_REDUCTION_TYPE )                                                      \\" )
2336 cpp_quote( "                                 ( ( ( D3D12Filter ) >> D3D12_FILTER_REDUCTION_TYPE_SHIFT ) & D3D12_FILTER_REDUCTION_TYPE_MASK ) ) " )
2337 
2338 cpp_quote( "#define D3D12_DECODE_IS_COMPARISON_FILTER( D3D12Filter )                                                    \\" )
2339 cpp_quote( "                                 ( D3D12_DECODE_FILTER_REDUCTION( D3D12Filter ) == D3D12_FILTER_REDUCTION_TYPE_COMPARISON ) " )
2340 
2341 cpp_quote( "#define D3D12_DECODE_IS_ANISOTROPIC_FILTER( D3D12Filter )                                               \\" )
2342 cpp_quote( "                            ( ( ( D3D12Filter ) & D3D12_ANISOTROPIC_FILTERING_BIT ) &&                  \\" )
2343 cpp_quote( "                            ( D3D12_FILTER_TYPE_LINEAR == D3D12_DECODE_MIN_FILTER( D3D12Filter ) ) &&   \\" )
2344 cpp_quote( "                            ( D3D12_FILTER_TYPE_LINEAR == D3D12_DECODE_MAG_FILTER( D3D12Filter ) ) )      " )
2345 
