6130 cpp_quote("//      Pointer to returned interface. May be NULL.")
6131 cpp_quote("//")
6132 cpp_quote("// Return Values")
6133 cpp_quote("//  Any of those documented for ")
6134 cpp_quote("//          CreateDXGIFactory1")
6135 cpp_quote("//          IDXGIFactory::EnumAdapters")
6136 cpp_quote("//          D3D12CreateDevice")
6137 cpp_quote("//")
6138 cpp_quote("
6139 cpp_quote("typedef HRESULT (WINAPI* PFN_D3D12_CREATE_DEVICE)( _In_opt_ IUnknown*, ")
6140 cpp_quote("    D3D_FEATURE_LEVEL, ")
6141 cpp_quote("    _In_ REFIID, _COM_Outptr_opt_ void** );")
6142 cpp_quote("")
6143 cpp_quote("HRESULT WINAPI D3D12CreateDevice(")
6144 cpp_quote("    _In_opt_ IUnknown* pAdapter,")
6145 cpp_quote("    D3D_FEATURE_LEVEL MinimumFeatureLevel,")
