6156 cpp_quote("// --------------------------------------------------------------------------------------------------------------------------------")
6157 cpp_quote("// D3D12EnableExperimentalFeatures")
6158 cpp_quote("//")
6159 cpp_quote("// Pass in a list of feature GUIDs to be enabled together.")
6160 cpp_quote("// ")
6161 cpp_quote("// If a particular feature requires some configuration information on enablement, it will have")
6162 cpp_quote("// a configuration struct that can be passed alongside the GUID.")
6163 cpp_quote("// ")
6164 cpp_quote("// Some features might use an interface IID as the GUID.  For these, once the feature is enabled via")
6165 cpp_quote("// D3D12EnableExperimentalFeatures, D3D12GetDebugInterface can then be called with the IID to retrieve the interface")
6166 cpp_quote("// for manipulating the feature.  This allows for control that might not cleanly be expressed by just ")
6167 cpp_quote("// the configuration struct that D3D12EnableExperimentalFeatures provides.")
6168 cpp_quote("//")
6169 cpp_quote("// If this method is called and a change to existing feature enablement is made, ")
6170 cpp_quote("// all current D3D12 devices are set to DEVICE_REMOVED state, since under the covers there is really only one")
6171 cpp_quote("// singleton device for a process.  Removing the devices when configuration changes prevents")
6172 cpp_quote("// mismatched expectations of how a device is supposed to work after it has been created from the app's point of view.")
6173 cpp_quote("//")
6174 cpp_quote("// The call returns E_NOINTERFACE if an unrecognized feature is passed in or Windows Developer mode is not on.")
6175 cpp_quote("// The call returns E_INVALIDARG if the configuration of a feature is incorrect, the set of features passed")
6176 cpp_quote("// in are known to be incompatible with each other, or other errors.")
6177 cpp_quote("// Returns S_OK otherwise.")
6178 cpp_quote("//")
6179 cpp_quote("// --------------------------------------------------------------------------------------------------------------------------------")
6180 cpp_quote("HRESULT WINAPI D3D12EnableExperimentalFeatures(")
6181 cpp_quote("    UINT                                    NumFeatures,")
6182 cpp_quote("    _In_count_(NumFeatures) const IID*     pIIDs,")
6183 cpp_quote("    _In_opt_count_(NumFeatures) void*      pConfigurationStructs,")
6184 cpp_quote("    _In_opt_count_(NumFeatures) UINT*      pConfigurationStructSizes);")
6185 cpp_quote("")
6186 cpp_quote("// --------------------------------------------------------------------------------------------------------------------------------")
6187 cpp_quote("// Experimental Feature: D3D12ExperimentalShaderModels")
6188 cpp_quote("//")
6189 cpp_quote("// Use with D3D12EnableExperimentalFeatures to enable experimental shader model support,")
6190 cpp_quote("// meaning shader models that haven't been finalized for use in retail.")
6191 cpp_quote("//")
6192 cpp_quote("// Enabling D3D12ExperimentalShaderModels needs no configuration struct, pass NULL in the pConfigurationStructs array.")
6193 cpp_quote("//")
6194 cpp_quote("// --------------------------------------------------------------------------------------------------------------------------------")
6195 cpp_quote("static const UUID D3D12ExperimentalShaderModels = { /* 76f5573e-f13a-40f5-b297-81ce9e18933f */")
6196 cpp_quote("    0x76f5573e,")
